#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
patch_geo_warehouse.py — Kit 29c (Geo Warehouse + productList unwrap)
=====================================================================
التشخيص اللايف (مؤكد بالتوثيق الرسمي ديال listV2):
  1. countryCode = "filter products with inventory in specified countries"
     = بلد المخزن، ماشي بلد التوصيل! MA بلا مخزن CJ → 0 نتائج شرعية.
  2. الشكل الحقيقي ديال الجواب: content[i] = مجموعة فيها productList[]
     → الـ mapping القديم كان كياخد content[i].id (غير موجود) → 0 منتجات
     حتى مع totalRecords=531!

الحل (v3.2):
  · globalWarehouseList (مجاني، كاش 24h) كيحدد البلدان اللي عندها مخازن
    → ليهم فقط كيتصيفط countryCode؛ الباقي كاطالوغ عالمي + geo.filterMode
  · فكّك content[].productList مع حماية للشكل المسطح
  · geo كتدخل الكاش (hits كيرجعو geo كاملة)

يخدم من جذر الـ backend (الفولدر اللي فيه server.js).
Backup: routes/cjLiveBridge.js.bak-kit29c — Idempotent.
"""
import base64, os, shutil, sys

FILES = {"backend/routes/cjLiveBridge.js": "", "verify_live_pipeline.py": ""}
BACKUP = ".bak-kit29c"
B = lambda name: base64.b64decode(FILES[name]).decode("utf-8")

def detect_tree():
    if os.path.exists("server.js") and os.path.exists("routes"):
        return "backend"
    return None

def main():
    if detect_tree() != "backend":
        print("❌ شغل هاد السكريبت من جذر الـ BACKEND (الفولدر اللي فيه server.js)")
        sys.exit(1)

    p = "routes/cjLiveBridge.js"
    if not os.path.exists(p):
        print(f"❌ {p} ما كاينش — ركب Kit 29 (Geo Flow) الأول")
        sys.exit(1)

    src = open(p, encoding="utf-8").read()
    if "[geo-warehouse]" in src:
        print("✓ cjLiveBridge.js — رقعة kit29c مركبة مسبقاً (skip — idempotent)")
        return

    bak = p + BACKUP
    if not os.path.exists(bak):
        shutil.copy2(p, bak)
        print(f"♻ backup → {bak}")
    else:
        print(f"ℹ backup قديم محفوظ ({bak})")

    write(p, B("backend/routes/cjLiveBridge.js"))

    chk = open(p, encoding="utf-8").read()
    if "[geo-warehouse]" not in chk:
        print("❌ فحص بعد الكتابة فشل — المجلة ما فيهاش الرقعة!")
        sys.exit(1)
    print("✚ routes/cjLiveBridge.js — v3.2 (فلتر المخازن + فكّك productList + envelope surfacing)")
    print("  [NEXT] commit + push → Render redeploy → python verify_live_pipeline.py")

def write(path, content):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(content)

if __name__ == "__main__":
    main()
